// À ADAPTER : les seuls réglages du workflow. Le jeton reste « change-moi » dans le fichier
// commité ; mettez la valeur d'API_TOKEN dans n8n. Contrôle de santé de l'API.
const parametres = {
  valideur: 'votre.adresse@gmail.com',             // reçoit les alertes et les dossiers à valider
  expediteur: 'Copilote IFRS 17 <votre.adresse@gmail.com>',  // l'adresse du compte SMTP
  api: 'http://127.0.0.1:8000',
  jeton: 'change-moi',
};
return [{ json: { parametres } }];

// Compare à l'état précédent (gardé dans le workflow) : une alerte à la panne, une au retour,
// jamais une toutes les 15 minutes. Les données statiques ne persistent qu'en production (workflow activé).
const memo = $getWorkflowStaticData('global');
const ok = $input.first().json.status === 'ok';
const avant = memo.etat ?? 'ok';
memo.etat = ok ? 'ok' : 'panne';
const p = $('Paramètres (santé)').first().json.parametres;
const detail = ok ? '' : String($input.first().json.error?.message ?? JSON.stringify($input.first().json)).slice(0, 500);
return [{ json: { parametres: p, changement: memo.etat !== avant, etat: memo.etat, detail,
  version: $input.first().json.version ?? '' } }];

