// À ADAPTER : les seuls réglages du workflow. Le jeton reste « change-moi » dans le fichier
// commité ; mettez la valeur d'API_TOKEN dans n8n. Rapport hebdomadaire.
const parametres = {
  valideur: 'votre.adresse@gmail.com',             // reçoit les alertes et les dossiers à valider
  expediteur: 'Copilote IFRS 17 <votre.adresse@gmail.com>',  // l'adresse du compte SMTP
  api: 'http://127.0.0.1:8000',
  jeton: 'change-moi',
};
return [{ json: { parametres } }];

const d = $input.first().json;
const p = $('Paramètres (rapport)').first().json.parametres;
const pct = x => `${Math.round((x || 0) * 100)} %`;
const s = d.par_statut || {};
const semaine = (d.par_jour || []).reduce((a, j) => a + j.dossiers, 0);
const ligne = (k, v) => `<tr><td style="padding:6px 12px;border-bottom:1px solid #ddd">${k}</td><td style="padding:6px 12px;border-bottom:1px solid #ddd;text-align:right"><b>${v}</b></td></tr>`;
const attente = (d.en_attente || []).map(w => `<li>${w.case_id} (depuis ${w.depuis.slice(0, 10)})</li>`).join('') || '<li>aucun</li>';
const html = `<div style="font-family:Segoe UI,Arial,sans-serif;color:#1B2A41;max-width:620px">
<h2 style="font-family:Georgia,serif">IFRS 17 Copilot · rapport de la semaine</h2>
<table style="border-collapse:collapse;width:100%">${[
  ligne('Dossiers déposés sur 7 jours', semaine), ligne('Dossiers au registre (total)', d.dossiers),
  ligne('Note produite sans intervention', pct(d.taux_note_directe)), ligne('Validation humaine demandée', pct(d.taux_validation_humaine)),
  ligne('Validés / rejetés', `${s.validee || 0} / ${s.rejetee || 0}`), ligne('En attente d\'un valideur', s.validation_humaine || 0),
  ligne('Durée médiane d\'analyse', d.duree_mediane_s == null ? '—' : `${Math.round(d.duree_mediane_s)} s`),
  ligne('Appels LLM par dossier', d.appels_llm_moyens), ligne('Coût des modèles', `${d.cout_total_usd} $`),
].join('')}</table>
<h3 style="font-family:Georgia,serif">En attente de validation</h3><ul>${attente}</ul>
<p style="color:#6B7A8F;font-size:13px">Détail et piste d'audit : site, pages Tableau de bord et Dossiers.</p></div>`;
return [{ json: { parametres: p, html } }];
